import { cn } from "@/lib/cn";

/**
 * マーカーで描いたあしらい。すべて装飾なので aria-hidden。
 * チゼル（角芯）マーカーを模していて、ペン先の角度と進行方向の差で太さが決まり、
 * 線の端は斜めにスパッと切れる。縁もわずかに不揃いにしてインクのにじみを出している。
 * 余白にだけ置き、顔や文字を隠さないこと（DESIGN.md）。
 */

