/**
 * 文字にマーカーを引いた見た目。
 *
 * `leading-none` で外枠の高さを 1em（＝文字の字面）に固定し、そこを基準に位置を決めている。
 * 見出しごとの line-height の違いでズレないよう、位置はすべて em 基準。
 * 帯を先に敷き、文字を上に重ねるので文字が潰れない。
 * 白抜き文字に使うと帯と重なった部分のコントラストが落ちるので、
 * その場合は帯を薄くかけるか、下に敷く形にする。
 *
 * 括弧や句点は字面の外に余白を持つので、行末が「。」のときなどは
 * `start` / `end` を足して帯の長さを実際の文字幅に合わせる。
 */
export function MarkedText({
  children,
  className,
  /** 左端の位置。正の値で内側に詰める */
  start = "0em",
  /** 右端の位置。正の値で内側に詰める */
  end = "0em",
  /** 文字の底ラインから下にはみ出す量 */
  drop = "0.02em",
  /** 帯の高さ。文字の字面（約0.88em）に対する割合で見え方が決まる */
  height = "0.5em",
}: {
  children: React.ReactNode;
  className?: string;
  start?: string;
  end?: string;
  drop?: string;
  height?: string;
}) {
  return (
    <span className={cn("relative inline-block leading-none", className)}>
      <span
        aria-hidden="true"
        className="absolute"
        style={{ left: start, right: end, bottom: `calc(-1 * ${drop})`, height }}
      >
        <MarkerHighlight />
      </span>
      <span className="relative">{children}</span>
    </span>
  );
}

